const RULES="rules_version = '2';\nservice cloud.firestore {\n  match /databases/{database}/documents {\n    function signed() { return request.auth != null; }\n    function isTeacher(sid) {\n      return signed() && get(/databases/$(database)/documents/sesiones/$(sid)).data.ownerUid == request.auth.uid;\n    }\n    function validOption(stage, id, cost) {\n      return (stage == 0 && ((id == 'a1' && cost == 7) || (id == 'a3' && cost == 12) || (id == 'a4' && cost == 6) || (id == 'a5' && cost == 16)))\n        || (stage == 1 && ((id == 'b1' && cost == 6) || (id == 'b2' && cost == 11) || (id == 'b3' && cost == 13) || (id == 'b5' && cost == 12)))\n        || (stage == 2 && ((id == 'c1' && cost == 8) || (id == 'c2' && cost == 15) || (id == 'c3' && cost == 7) || (id == 'c4' && cost == 5)))\n        || (stage == 3 && ((id == 'd1' && cost == 5) || (id == 'd3' && cost == 10) || (id == 'd4' && cost == 9) || (id == 'd5' && cost == 12)))\n        || (stage == 4 && ((id == 'e1' && cost == 6) || (id == 'e2' && cost == 7) || (id == 'e3' && cost == 9) || (id == 'e4' && cost == 11)));\n    }\n    function validDecision(d, stage) {\n      return d is map && d.stage == stage && d.options is list\n        && d.options.size() >= 2 && d.options.size() <= 4\n        && d.reason is string && d.reason.size() >= 18\n        && d.cost is int\n        && d.options[0] is map && validOption(stage, d.options[0].id, d.options[0].cost)\n        && d.options[1] is map && validOption(stage, d.options[1].id, d.options[1].cost)\n        && d.options[0].id != d.options[1].id\n        && (d.options.size() < 3 || (d.options[2] is map && validOption(stage, d.options[2].id, d.options[2].cost) && d.options[0].id != d.options[2].id && d.options[1].id != d.options[2].id))\n        && (d.options.size() < 4 || (d.options[3] is map && validOption(stage, d.options[3].id, d.options[3].cost) && d.options[0].id != d.options[3].id && d.options[1].id != d.options[3].id && d.options[2].id != d.options[3].id))\n        && d.cost == d.options[0].cost + d.options[1].cost + (d.options.size() > 2 ? d.options[2].cost : 0) + (d.options.size() > 3 ? d.options[3].cost : 0);\n    }\n    function sameHistory(next, old) {\n      return old.decisions.size() == 0\n        || (next.decisions[0] == old.decisions[0]\n          && (old.decisions.size() < 2 || next.decisions[1] == old.decisions[1])\n          && (old.decisions.size() < 3 || next.decisions[2] == old.decisions[2])\n          && (old.decisions.size() < 4 || next.decisions[3] == old.decisions[3])\n          && (old.decisions.size() < 5 || next.decisions[4] == old.decisions[4]));\n    }\n    function totalCost(ds) {\n      return (ds.size() > 0 ? ds[0].cost : 0)\n        + (ds.size() > 1 ? ds[1].cost : 0)\n        + (ds.size() > 2 ? ds[2].cost : 0)\n        + (ds.size() > 3 ? ds[3].cost : 0)\n        + (ds.size() > 4 ? ds[4].cost : 0);\n    }\n    function validAppend(next, old) {\n      return next.diff(old).affectedKeys().hasOnly(['decisions', 'status', 'updatedAt'])\n        && old.decisions is list && next.decisions is list && old.decisions.size() < 5\n        && next.decisions.size() == old.decisions.size() + 1\n        && sameHistory(next, old)\n        && validDecision(next.decisions[old.decisions.size()], old.decisions.size())\n        && totalCost(next.decisions) <= 100\n        && next.status == (next.decisions.size() == 5 ? 'ready_to_submit' : 'in_progress')\n        && next.updatedAt is int;\n    }\n    function validFinalize(next, old) {\n      return next.diff(old).affectedKeys().hasOnly(['status', 'submittedAt', 'finishedAt', 'updatedAt'])\n        && old.status == 'ready_to_submit' && old.decisions is list && old.decisions.size() == 5\n        && next.status == 'finalized' && next.submittedAt == request.time\n        && next.finishedAt == request.time && next.updatedAt == request.time;\n    }\n    function validPresentationChange(sid, next, old) {\n      return isTeacher(sid)\n        && next.diff(old).affectedKeys().hasOnly(['status', 'presentedAt', 'updatedAt'])\n        && ((old.status == 'finalized' && next.status == 'presented' && next.presentedAt == request.time && next.updatedAt == request.time)\n          || (old.status == 'presented' && next.status == 'finalized' && next.presentedAt == null && next.updatedAt == request.time));\n    }\n    match /sesiones/{sid} {\n      allow create: if signed() && request.auth.token.firebase.sign_in_provider == 'password'\n        && request.resource.data.ownerUid == request.auth.uid\n        && request.resource.data.keys().hasAll(['ownerUid', 'presented', 'rouletteHistory', 'createdAt', 'title']);\n      allow get: if signed();\n      allow list: if false;\n      allow update, delete: if isTeacher(sid);\n      match /equipos/{uid} {\n        allow read: if isTeacher(sid) || (signed() && request.auth.uid == uid);\n        allow create: if signed() && request.auth.uid == uid && request.resource.data.uid == uid\n          && request.resource.data.keys().hasAll(['uid', 'name', 'members', 'decisions', 'createdAt', 'updatedAt', 'finishedAt', 'submittedAt', 'status'])\n          && request.resource.data.status == 'registered' && request.resource.data.decisions is list\n          && request.resource.data.decisions.size() == 0 && request.resource.data.submittedAt == null;\n        allow update: if signed() && ((request.auth.uid == uid && resource.data.uid == uid && request.resource.data.uid == uid\n          && (validAppend(request.resource.data, resource.data) || validFinalize(request.resource.data, resource.data)) )\n          || validPresentationChange(sid, request.resource.data, resource.data));\n        allow delete: if isTeacher(sid);\n      }\n    }\n  }\n}\r\n\r\n\r\n"
