function openPage(next){view=next;render();window.scrollTo(0,0)}
function total(t){return (t?.decisions||[]).reduce((s,d)=>s+(Number(d.cost)||0),0)}
function left(t){return 100-total(t)}
function allDecisions(t){return t?.decisions?.length===STAGES.length}
function complete(t){return allDecisions(t)&&Boolean(t.submittedAt)&&['finalized','presented'].includes(t.status)}
function statusOf(t){if(session?.presented?.includes(t?.uid)||t?.status==='presented')return 'Ya expuso';if(complete(t))return 'Finalizado';if(allDecisions(t)||t?.status==='ready_to_submit')return 'Listo para enviar';if(chosen(t)>0||t?.status==='in_progress')return 'En progreso';return 'Registrado'}
function stampMillis(value){return typeof value?.toMillis==='function'?value.toMillis():(Number(value)||0)}
function sortTeams(list){return [...list].sort((a,b)=>{const af=complete(a),bf=complete(b);if(af!==bf)return af?-1:1;if(af)return stampMillis(a.submittedAt)-stampMillis(b.submittedAt);return stampMillis(a.createdAt)-stampMillis(b.createdAt)})}
function performance(t){const score={profitability:52,satisfaction:50,reputation:50,innovation:48,competitiveness:50};for(const decision of t?.decisions||[])for(const option of decision.options||[])for(const [key,value] of Object.entries(OPTION_EFFECTS[option.id]||{}))score[key]+=value;score.profitability+=(left(t)-35)*.12;return METRICS.map(([key,label])=>({key,label,value:Math.max(0,Math.min(100,Math.round(score[key])))}))}
function mine(){return teams.find(t=>t.uid===currentUid)}
