let loadScripts=null;
function firebaseScripts(){if(window.firebase)return Promise.resolve();if(loadScripts)return loadScripts;loadScripts=(async()=>{for(let name of ['app','auth','firestore'])await new Promise((res,rej)=>{let sc=document.createElement('script');sc.src='https://www.gstatic.com/firebasejs/10.12.5/firebase-'+name+'-compat.js';sc.onload=res;sc.onerror=()=>rej(new Error('No fue posible cargar los recursos de Firebase; comprobá la conexión.'));document.head.append(sc)})})();return loadScripts}
function validConf(c){return c&&typeof c.apiKey==='string'&&typeof c.projectId==='string'&&typeof c.appId==='string'}
async function initFirebase(c){if(!validConf(c))throw Error('Falta apiKey, projectId o appId en el JSON de Firebase.');await firebaseScripts();const appName='uamS11';fireApp=window.firebase.apps.find(a=>a.name===appName)||window.firebase.initializeApp(c,appName);auth=fireApp.auth();db=fireApp.firestore();await auth.setPersistence(window.firebase.auth.Auth.Persistence.LOCAL);config=c;remote=true}
function authReadyPromise(){if(!auth)return Promise.reject(Error('Firebase sin inicializar'));return new Promise((resolve,reject)=>{const unsub=auth.onAuthStateChanged(user=>{unsub();if(user)resolve(user);else auth.signInAnonymously().then(resolve,reject)},reject)})}
async function connectTeacher(){const raw=$('#firebaseJson').value.trim(),email=$('#firebaseEmail').value.trim(),pass=$('#firebasePass').value;try{let c=JSON.parse(raw);if(!email||!pass)throw Error('Ingresá tu correo y contraseña docente de Firebase Authentication.');remoteBusy=true;liveErr='';await initFirebase(c);const cred=await auth.signInWithEmailAndPassword(email,pass);teacherEmail=email;safeStore.setItem(CONFIGKEY,JSON.stringify(c));const sid=id().replace(/-/g,'').slice(0,18).toUpperCase();await db.collection('sesiones').doc(sid).set({id:sid,ownerUid:cred.user.uid,presented:[],rouletteHistory:[],createdAt:Date.now(),title:'UAM Estrategia Empresarial S11'});session={id:sid,ownerUid:cred.user.uid,presented:[],rouletteHistory:[],createdAt:Date.now()};safeStore.setItem(LASTSIDKEY,sid);teams=[];notificationsReady=false;notifiedIds.clear();unread=0;subscribeTeacher();say('Firebase conectado. Sesión '+sid+' creada; proyectá el QR para que los estudiantes ingresen.');openPage('teacher')}catch(e){liveErr=(e.message||String(e));remote=false;openPage('setup')}finally{remoteBusy=false}}
async function restoreTeacher(){
 const sid=safeStore.getItem(LASTSIDKEY);if(!sid||!validConf(config)||isStudentLink)return;
 try{await initFirebase(config);const u=await new Promise(resolve=>{let unsub=auth.onAuthStateChanged(x=>{unsub();resolve(x)},()=>resolve(null))});
  if(!u||u.isAnonymous){remote=false;return}
  const d=await db.collection('sesiones').doc(sid).get();if(!d.exists||d.data().ownerUid!==u.uid){remote=false;return}
  session={...d.data(),id:d.id};teams=[];notificationsReady=false;notifiedIds.clear();subscribeTeacher();render();
 }catch(e){remote=false;console.warn('No se pudo restaurar la sesión docente:',e)}
}
function subscribeTeacher(){
  teamListener?.();sessionListener?.();
  sessionListener=db.collection('sesiones').doc(session.id).onSnapshot(s=>{if(s.exists){session={...s.data(),id:s.id};if(useTeacher())render()}},e=>say('Error de sesión: '+e.message));
  teamListener=db.collection('sesiones').doc(session.id).collection('equipos').onSnapshot(s=>{teams=sortTeams(s.docs.map(d=>d.data()));bell();if(useTeacher())render()},e=>say('No se pueden leer las decisiones: '+e.message));
}
async function connectStudent(){if(!isStudentLink||!targetSid)return;if(!config){say('El enlace necesita la configuración de Firebase. Solicitá un QR actualizado al docente.');render();return}try{await initFirebase(config);const user=await authReadyPromise();let snap=await db.collection('sesiones').doc(targetSid).get();if(!snap.exists)throw Error('La sesión no existe. Pedí un QR nuevo.');session={...snap.data(),id:snap.id};const own=await db.collection('sesiones').doc(session.id).collection('equipos').doc(user.uid).get();currentUid=user.uid;safeStore.setItem(KEY+'_uid',user.uid);if(own.exists){teams=[own.data()];view='student'}else teams=[];teamListener?.();teamListener=db.collection('sesiones').doc(session.id).collection('equipos').doc(user.uid).onSnapshot(d=>{if(d.exists){teams=[d.data()];if(view==='student'||view==='register')render()}},e=>say('Error de sincronización: '+e.message));render()}catch(e){remote=false;liveErr=e.message;say('No se pudo conectar: '+e.message);render()}}
function act(action,target){switch(action){case 'home':openPage('home');break;case 'register':openPage(mine()?'student':'register');break;case 'teacher':if(isStudentLink)return;unread=0;openPage('teacher');break;case 'student':openPage(mine()?'student':'register');break;case 'qr':unread=0;openPage('qr');break;case 'roulette':spinWinner=null;openPage('roulette');break;case 'setup':openPage('setup');break;case 'toggle':selectOption(target);break;case 'auto-adjust':adjustAffordable();break;case 'confirm':saveDecision();break;case 'submit-final':submitFinal();break;case 'seed':seed();break;case 'pick-team':adminSelected=target;render();break;case 'project-team':projectSelected=target;projStep=0;openPage('project');break;case 'prev-project':projStep=Math.max(0,projStep-1);render();break;case 'next-project':projStep=Math.min(5,projStep+1);render();break;case 'project-winner':if(spinWinner){projectSelected=spinWinner.uid;projStep=0;openPage('project')}break;case 'mark-presented':markPresented(target||projectSelected);break;case 'undo-presented':markPresented(target,true);break;case 'spin':spin();break;case 'export':csv();break;case 'copy-url':clipboard(qrUrl());break;case 'copy-rules':clipboard(RULES);break;case 'connect-firebase':connectTeacher();break;case 'toggle-sound':bellSound=!bellSound;if(bellSound)beep();render();break;case 'reset-history':resetRouletteHistory();break;case 'open-student-tab':window.open(qrUrl(),'_blank','noopener');break;}}
$('#content').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)act(b.dataset.action,b.dataset.id)});$('#closeTop').onclick=()=>parent.postMessage({type:'UAM_ACTIVITY_CLOSE'},'*');$('#teacherTop').onclick=()=>act('teacher');$('#studentTop').onclick=()=>act('student');$('#bellBtn').onclick=()=>{unread=0;bellSound=true;beep();openPage('teacher')};
window.addEventListener('storage',e=>{if(e.key===KEY&&!remote){const data=readLocal();session=data.session;teams=data.teams;bell();render()}});
window.addEventListener('message',e=>{if(e.data?.type==='UAM_ACTIVITY_VIEW'&&['home','student','teacher','qr','roulette'].includes(e.data.view)){openPage(e.data.view)}});
window.addEventListener('keydown',e=>{if(view==='project'&&e.key==='ArrowRight'){e.preventDefault();act('next-project')}if(view==='project'&&e.key==='ArrowLeft'){e.preventDefault();act('prev-project')}if(e.key==='Escape'&&!isStudentLink)parent.postMessage({type:'UAM_ACTIVITY_CLOSE'},'*')});
render();if(isStudentLink)connectStudent();else restoreTeacher();
